<template><div v-if="items.length" class="widget-menu" ref="root"><button ref="trigger" type="button" class="widget-menu-trigger" :aria-label="label" aria-haspopup="menu" :aria-expanded="open" @click="toggle" @keydown.down.prevent="show" data-widget-more>⋮</button><div v-if="open" class="widget-menu-options" role="menu" :aria-label="label" @keydown="key"><button v-for="item in items" :key="item.id" type="button" role="menuitem" :disabled="item.disabled" :data-widget-menu-item="item.id" @click="select(item.id)">{{item.label}}</button></div></div></template>
<script setup lang="ts">
import {nextTick,onMounted,onUnmounted,ref} from 'vue'
defineProps<{label:string;items:Array<{id:string;label:string;disabled?:boolean}>}>()
const emit=defineEmits<{(e:'select',id:string):void}>(),open=ref(false),root=ref<HTMLElement|null>(null),trigger=ref<HTMLButtonElement|null>(null)
async function show(){open.value=true;await nextTick();root.value?.querySelector<HTMLButtonElement>('[role=menuitem]:not(:disabled)')?.focus()}
function toggle(){if(open.value)open.value=false;else void show()}
function select(id:string){open.value=false;trigger.value?.focus({preventScroll:true});emit('select',id)}
function key(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();open.value=false;trigger.value?.focus({preventScroll:true})}else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const nodes=Array.from(root.value?.querySelectorAll<HTMLButtonElement>('[role=menuitem]:not(:disabled)')||[]),index=nodes.indexOf(document.activeElement as HTMLButtonElement);nodes[event.key==='Home'?0:event.key==='End'?nodes.length-1:(index+(event.key==='ArrowDown'?1:-1)+nodes.length)%nodes.length]?.focus()}else if(event.key==='Tab')open.value=false}
function outside(event:Event){if(!root.value?.contains(event.target as Node))open.value=false}
onMounted(()=>document.addEventListener('click',outside));onUnmounted(()=>document.removeEventListener('click',outside))
</script>
<style scoped>
.widget-menu{position:relative;display:flex;flex:none}.widget-menu-trigger{width:var(--widget-more-width,32px);min-height:var(--widget-more-height,32px);display:grid;place-items:center;background:none!important;border:var(--widget-more-border,1px solid var(--c-line,var(--btn-border-color)))!important;border-radius:var(--widget-more-radius,6px);font:var(--widget-more-font,22px/1 Arial)!important;color:var(--widget-more-ink,var(--c-text,var(--app-container_title-color)))!important;cursor:pointer}.widget-menu-options{position:absolute;right:0;top:calc(100% + 6px);min-width:180px;max-width:min(260px,80vw);padding:6px;z-index:80;background:var(--c-panel,var(--card-bg-color));border:1px solid var(--c-line,var(--border-color));box-shadow:0 10px 30px #17243e22;border-radius:9px}.widget-menu-options button{display:block;width:100%;min-height:40px;padding:9px 12px!important;text-align:left;background:none;border:0;border-radius:5px;font:14px/1.5 Arial,"Microsoft YaHei",sans-serif!important;color:var(--c-text,var(--app-container_title-color));cursor:pointer;white-space:normal}.widget-menu-options button:hover,.widget-menu-options button:focus-visible{background:var(--c-soft,#8881)}@media(pointer:coarse){.widget-menu-trigger{min-width:44px;min-height:44px}.widget-menu-options button{min-height:44px}}
</style>
